// Whether a call of `f` is a plain `invoke` (no standard operation, no
// procedure inlined or specialized).
pub fn r_plain_callee_p(f: &'static Cx, args: Cxs, e: Cenv) -> bool {
    let tagcase_ = f;
    match *tagcase_ {
        Cx::XVar(name, a) => {
            (std_written_p(name) || {
                let l = if std_marked_p(name) {
                    nil::<&'static Loc>()
                } else {
                    c_where(e, name)
                };
                (not(null_p(l)) && {
                    let tagcase_ = car(l);
                    match *tagcase_ {
                        Loc::AtGlobal(c) => {
                            (null_p(r_inline_named(get(cg_inlines()), name, size(args), -1i64)) && null_p(r_special_named(get(cg_specials()), name, size(args), -1i64)))
                        }
                        Loc::AtSlot(i) => {
                            true
                        }
                        Loc::AtFree(i) => {
                            true
                        }
                        _ => {
                            let y = tagcase_;
                            false
                        }
                    }
                })
            })
        }
        _ => {
            let y = tagcase_;
            true
        }
    }
}

// Whether no binding of `bs` but the `i`th mentions `name`.
pub fn r_unmentioned_p(bs: Cbinds, name: Str, i: i64, k: i64) -> bool {
    (null_p(bs) || ((i64_eq(k, i) || {
        let tagcase_ = car(bs);
        match *tagcase_ {
            Cbind::Cbind(n, x) => {
                not(c_mentions_p(x, name))
            }
        }
    }) && r_unmentioned_p(cdr(bs), name, i, i64_plus(k, 1i64))))
}

pub fn r_nth_bind(mut bs: Cbinds, mut i: i64) -> &'static Cbind {
    loop {
        if i64_eq(i, 0i64) {
            return car(bs);
        } else {
            (bs, i) = (cdr(bs), i64_minus(i, 1i64));
            continue;
        }
    }
}

// Whether `letrec` binding `i` of `bs` is a join point (C253, Fixpt's
// `c-join-ok?`): a lambda, of no region, whose body calls it only in tail
// position, as the `letrec`'s body does, and that no sibling mentions; so
// no closure is made of it, and its calls are jumps.
pub fn r_join_ok_p(bs: Cbinds, body: &'static Cx, i: i64) -> bool {
    let tagcase_ = r_nth_bind(bs, i);
    match *tagcase_ {
        Cbind::Cbind(name, x) => {
            let l = lambda_of(x);
            (not(null_p(l)) && {
                let tagcase_ = car(l);
                match *tagcase_ {
                    Lparts::Lparts(ps, lbody, region) => {
                        let n = size(ps);
                        (null_p(region) && not(string_member_p(name, ps)) && c_loops_only(lbody, name, n, true) && c_loops_only(body, name, n, true) && r_unmentioned_p(bs, name, i, 0i64))
                    }
                }
            })
        }
    }
}

// Each binding of `bs`: whether it is a join point (in tail position only).
pub fn r_join_flags_from(bs: Cbinds, body: &'static Cx, tail: bool, i: i64, n: i64) -> List<bool> {
    if i64_gt_eq(i, n) {
        nil::<bool>()
    } else {
        kayak_rt::heap_cons((tail && r_join_ok_p(bs, body, i)), r_join_flags_from(bs, body, tail, i64_plus(i, 1i64), n))
    }
}

pub fn r_join_flags(bs: Cbinds, body: &'static Cx, tail: bool) -> List<bool> {
    r_join_flags_from(bs, body, tail, 0i64, size(bs))
}

pub fn r_all_p(fs: List<bool>) -> bool {
    (null_p(fs) || (car(fs) && r_all_p(cdr(fs))))
}

// `te` with each of `bs`' names a loop, as a join point is to the stack
// compiler.
pub fn r_loop_names(mut te: Cenv, mut bs: Cbinds) -> Cenv {
    loop {
        if null_p(bs) {
            return te;
        } else {
            (te, bs) = ({
                let tagcase_ = car(bs);
                match *tagcase_ {
                    Cbind::Cbind(n, x) => {
                        c_extend(n, at_loop(), te)
                    }
                }
            }, cdr(bs));
            continue;
        }
    }
}

// `ps` bound as locals, onto `te`.
pub fn r_locals(mut ps: Strings, mut te: Cenv) -> Cenv {
    loop {
        if null_p(ps) {
            return te;
        } else {
            (ps, te) = (cdr(ps), c_extend(car(ps), at_slot(-1i64), te));
            continue;
        }
    }
}

// Whether bloblet form `op` itself never calls out: a field's read; a
// blobref's read, write, element or variant, in line; a product's field
// through a blobref (Fixpt's `extract`, C259).
pub fn r_bloblet_quiet_p(op: Str) -> bool {
    string_member_p(op, kayak_rt::heap_cons(str_lit("bloblet-ref"), kayak_rt::heap_cons(str_lit("blobref-get"), kayak_rt::heap_cons(str_lit("blobref-set!"), kayak_rt::heap_cons(str_lit("blobref-index"), kayak_rt::heap_cons(str_lit("blobref-variant!"), kayak_rt::heap_cons(str_lit("%blobref-field"), kayak_rt::nil())))))))
}

pub fn c_with_local(te: Cenv, n: Str) -> Cenv {
    c_extend(n, at_slot(-1i64), te)
}

/// Whether evaluating `x` may call or call out, and so collect (Fixpt's
/// `r-collects`). Loops do not. What register code declines is said
/// to, which does not matter.
pub fn r_collects(mut v: &'static Rview, mut x: &'static Cx, mut e: Cenv, mut me: Rthis, mut tail: bool) -> bool {
    loop {
        let tagcase_ = x;
        match *tagcase_ {
            Cx::XVar(n, a) => {
                let l = if std_marked_p(n) {
                    nil::<&'static Loc>()
                } else {
                    c_where(e, n)
                };
                return (null_p(l) && r_standard_value_name_p(std_named(n)) && (not(tail) || c_vsubr_p(std_named(n))));
            }
            Cx::XInt(n, a) => {
                return false;
            }
            Cx::XBool(b, a) => {
                return false;
            }
            Cx::XStr(s, a) => {
                return false;
            }
            Cx::XChar(ch, a) => {
                return false;
            }
            Cx::XFloat(f, a) => {
                return false;
            }
            Cx::XSym(s, a) => {
                return false;
            }
            Cx::XUnit(a) => {
                return false;
            }
            Cx::XLambda(ps, body, a) => {
                return not(tail);
            }
            Cx::XLetrec(bs, body, a) => {
                if (tail && r_all_p(r_join_flags(bs, body, true))) {
                    let inner = r_loop_names(e, bs);
                    return (r_collects(v, body, inner, me, tail) || r_collects_joins(v, bs, inner, me));
                } else {
                    return true;
                }
            }
            Cx::XIf(t, th, el, a) => {
                return (r_collects(v, t, e, me, false) || r_collects(v, th, e, me, tail) || r_collects(v, el, e, me, tail));
            }
            Cx::XLet(bs, body, a) => {
                return (r_collects_all(v, c_bound_exps(bs), e, me) || r_collects(v, body, e, me, tail));
            }
            Cx::XBegin(es, a) => {
                return r_collects_begin(v, es, e, me, tail);
            }
            Cx::XRegion(k, r, body, a) => {
                if (i64_eq(k, 0i64) || i64_eq(k, 3i64)) {
                    x = body;
                    continue;
                } else {
                    return true;
                }
            }
            Cx::XProj(y, a) => {
                x = y;
                continue;
            }
            Cx::XWith(m, ns, ks, body, a) => {
                (x, e) = (body, r_locals(ns, e));
                continue;
            }
            Cx::XExtract(p, i, a) => {
                (x, tail) = (p, false);
                continue;
            }
            Cx::XBloblet(op, i, args, a) => {
                if r_bloblet_quiet_p(op) {
                    return r_collects_all(v, args, e, me);
                } else {
                    return true;
                }
            }
            Cx::XTagcase(s, arms, els, k, a) => {
                return (r_collects(v, s, e, me, false) || r_collects_arms(v, arms, e, me, tail) || (not(null_p(els)) && {
                    let tagcase_ = car(els);
                    match *tagcase_ {
                        Cbind::Cbind(n, y) => {
                            r_collects(v, y, e, me, tail)
                        }
                    }
                }));
            }
            Cx::XApp(f, args, a) => {
                let n = size(args);
                let args_collect = r_collects_all(v, args, e, me);
                let loop_call = (tail && r_self_call_p(f, args, e, me));
                let inline = r_inline_op_p(f, args, e);
                let leaves = (rview_tail_leaves(v) && tail && i64_lt(n, register_regs()) && r_plain_callee_p(f, args, e) && not(r_collects(v, f, e, me, false)));
                return (args_collect || not((loop_call || inline || leaves || r_call_is_free_p(v, f, n, e, tail))));
            }
            _ => {
                let y = tagcase_;
                return true;
            }
        }
    }
}

/// Whether a call of global `f` with `n` arguments, in a fast version,
/// is no call: its own in tail position, a loop; or one inlined, whose
/// body calls nothing (C252).
pub fn r_call_is_free_p(v: &'static Rview, f: &'static Cx, n: i64, e: Cenv, tail: bool) -> bool {
    (rview_assuming(v) && {
        let tagcase_ = f;
        match *tagcase_ {
            Cx::XVar(name, a) => {
                let l = if std_marked_p(name) {
                    nil::<&'static Loc>()
                } else {
                    c_where(e, name)
                };
                (not(null_p(l)) && c_global_p(car(l)) && ((tail && rview_own_is_p(v, name, n)) || {
                    let i = r_inline_named(get(cg_inlines()), name, n, -1i64);
                    (not(null_p(i)) && {
                        let tagcase_ = car(i);
                        match *tagcase_ {
                            Rinline::Rinline(m, ps, body, at) => {
                                not(r_collects(v, body, r_locals(ps, nil::<&'static Centry>()), nil::<&'static This>(), tail))
                            }
                        }
                    })
                }))
            }
            _ => {
                let y = tagcase_;
                false
            }
        }
    })
}

/// Whether any of `bs`' lambdas' bodies, their parameters bound in `e`,
/// calls or calls out.
pub fn r_collects_joins(v: &'static Rview, bs: Cbinds, e: Cenv, me: Rthis) -> bool {
    (not(null_p(bs)) && ({
        let tagcase_ = car(bs);
        match *tagcase_ {
            Cbind::Cbind(n, x) => {
                let l = lambda_of(x);
                (null_p(l) || {
                    let tagcase_ = car(l);
                    match *tagcase_ {
                        Lparts::Lparts(ps, lbody, region) => {
                            r_collects(v, lbody, r_locals(ps, e), me, true)
                        }
                    }
                })
            }
        }
    } || r_collects_joins(v, cdr(bs), e, me)))
}

pub fn r_collects_all(v: &'static Rview, es: Cxs, e: Cenv, me: Rthis) -> bool {
    (not(null_p(es)) && (r_collects(v, car(es), e, me, false) || r_collects_all(v, cdr(es), e, me)))
}

pub fn r_collects_begin(v: &'static Rview, es: Cxs, e: Cenv, me: Rthis, tail: bool) -> bool {
    if null_p(es) {
        false
    } else if null_p(cdr(es)) {
        r_collects(v, car(es), e, me, tail)
    } else {
        (r_collects(v, car(es), e, me, false) || r_collects_begin(v, cdr(es), e, me, tail))
    }
}

pub fn r_collects_arms(v: &'static Rview, arms: List<&'static Carm>, e: Cenv, me: Rthis, tail: bool) -> bool {
    (not(null_p(arms)) && ({
        let tagcase_ = car(arms);
        match *tagcase_ {
            Carm::Carm(t, p, ns, body) => {
                r_collects(v, body, e, me, tail)
            }
        }
    } || r_collects_arms(v, cdr(arms), e, me, tail)))
}

